ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS content_mode text NOT NULL DEFAULT 'design' CHECK (content_mode IN ('design','plain','html')), ADD COLUMN IF NOT EXISTS plain_body text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS html_body text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS theme jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE public.email_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES public.accounts(id) ON DELETE CASCADE, name text NOT NULL, category text NOT NULL DEFAULT 'Saved', content_mode text NOT NULL DEFAULT 'design' CHECK (content_mode IN ('design','plain','html')), subject text NOT NULL DEFAULT '', blocks jsonb NOT NULL DEFAULT '[]'::jsonb, plain_body text NOT NULL DEFAULT '', html_body text NOT NULL DEFAULT '', theme jsonb NOT NULL DEFAULT '{}'::jsonb, provider_template_id text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.email_templates TO service_role;
ALTER TABLE public.email_templates ENABLE ROW LEVEL SECURITY;
CREATE INDEX email_templates_account_idx ON public.email_templates(account_id, created_at DESC);
CREATE UNIQUE INDEX email_templates_provider_uidx ON public.email_templates(provider_template_id) WHERE account_id IS NULL AND provider_template_id IS NOT NULL;
COMMENT ON TABLE public.email_templates IS 'Rows with account_id NULL are the platform library shared with every business; others are business-saved templates. Accessed only through server functions.';
CREATE OR REPLACE FUNCTION public.email_queue_campaign(_id uuid,_account uuid,_schedule timestamptz DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.email_campaigns; b public.email_bundles; count_contacts integer; recipients integer; BEGIN SELECT * INTO c FROM public.email_campaigns WHERE id=_id AND account_id=_account FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; IF c.status<>'draft' THEN RETURN c.total; END IF; IF EXISTS(SELECT 1 FROM public.accounts WHERE id=_account AND (suspended_at IS NOT NULL OR sending_suspended_at IS NOT NULL)) THEN RAISE EXCEPTION 'Sending is on hold for this business'; END IF; IF length(trim(c.subject))=0 OR length(trim(c.from_name))=0 OR length(trim(c.postal_address))<5 OR (CASE c.content_mode WHEN 'plain' THEN length(trim(c.plain_body))=0 WHEN 'html' THEN length(trim(c.html_body))=0 ELSE jsonb_array_length(c.blocks)=0 END) THEN RAISE EXCEPTION 'Complete subject, sender, address and email content'; END IF; IF NOT EXISTS(SELECT 1 FROM public.email_sending_domains WHERE account_id=_account AND status='verified' AND domain=split_part(lower(c.from_email),'@',2)) THEN RAISE EXCEPTION 'Verify your sender domain before sending'; END IF; IF c.list_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contact_lists WHERE id=c.list_id AND account_id=_account) THEN RAISE EXCEPTION 'List not found'; END IF; INSERT INTO public.email_bundles(account_id) VALUES(_account) ON CONFLICT DO NOTHING; SELECT * INTO b FROM public.email_bundles WHERE account_id=_account FOR UPDATE; IF b.plan='free' AND b.period_end<=now() THEN UPDATE public.email_bundles SET used=0,period_start=date_trunc('month',now()),period_end=date_trunc('month',now())+interval '1 month' WHERE account_id=_account RETURNING * INTO b; END IF; IF b.status<>'active' OR b.period_end<=now() THEN RAISE EXCEPTION 'Your email bundle needs renewal'; END IF; SELECT count(*) INTO count_contacts FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email); IF count_contacts>b.contact_limit THEN RAISE EXCEPTION 'Your contact count exceeds your email bundle. Choose a larger bundle.'; END IF; SELECT count(*) INTO recipients FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email) AND (c.list_id IS NULL OR EXISTS(SELECT 1 FROM public.profile_list_members m WHERE m.list_id=c.list_id AND m.profile_id=p.id)); IF recipients=0 THEN RAISE EXCEPTION 'No subscribed email contacts in this audience'; END IF; IF b.email_limit IS NOT NULL AND b.used+recipients>b.email_limit THEN RAISE EXCEPTION 'Monthly email allowance exceeded'; END IF; INSERT INTO public.email_recipients(campaign_id,account_id,profile_id,email,first_name) SELECT c.id,_account,p.id,p.email,p.first_name FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email) AND (c.list_id IS NULL OR EXISTS(SELECT 1 FROM public.profile_list_members m WHERE m.list_id=c.list_id AND m.profile_id=p.id)) ON CONFLICT DO NOTHING; UPDATE public.email_bundles SET used=used+recipients WHERE account_id=_account; UPDATE public.email_campaigns SET total=recipients,status='queued',schedule_at=_schedule,updated_at=now() WHERE id=c.id; RETURN recipients; END $$; REVOKE ALL ON FUNCTION public.email_queue_campaign(uuid,uuid,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_queue_campaign(uuid,uuid,timestamptz) TO service_role;